import json, glob

for f in glob.glob("/home/agent/.gemini/tmp/workspace/tool-outputs/session-fbe1d2fa-71ee-41d4-8e2d-1958ed5b15ea/*linear*.txt"):
    try:
        with open(f) as fp:
            text = fp.read()
            idx = text.find("{")
